package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class CacheMaintenanceTest {
 private void cleanup(Path dir)throws Exception{try(java.util.stream.Stream<Path> files=Files.list(dir)){for(Path file:(Iterable<Path>)files::iterator)Files.deleteIfExists(file);}Files.deleteIfExists(dir);}
 @Test public void removalReturnsWhileCacheQueueAndLockAreOccupied()throws Exception{ExecutorService io=CacheIo.create(),caller=Executors.newSingleThreadExecutor();Object lock=new Object();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);Path dir=Files.createTempDirectory("cache-remove-");Path file=Files.createFile(dir.resolve("entry.json"));try{io.execute(()->{synchronized(lock){entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}}});assertTrue(entered.await(3,TimeUnit.SECONDS));AtomicInteger submitted=new AtomicInteger();Executor injected=task->{submitted.incrementAndGet();io.execute(task);};caller.submit(()->CacheIo.remove(injected,lock,file.toFile())).get(3,TimeUnit.SECONDS);assertEquals(1,submitted.get());assertEquals(1,release.getCount());assertTrue(Files.exists(file));release.countDown();io.submit(()->{}).get(3,TimeUnit.SECONDS);assertFalse(Files.exists(file));}finally{release.countDown();caller.shutdownNow();io.shutdownNow();io.awaitTermination(3,TimeUnit.SECONDS);cleanup(dir);}}
 @Test public void removalFollowsEarlierSaveAndRemovesAtomicSidecars()throws Exception{ExecutorService io=CacheIo.create();Object lock=new Object();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicBoolean saved=new AtomicBoolean();Path dir=Files.createTempDirectory("cache-fifo-");Path file=dir.resolve("entry.json");try{Future<?> save=io.submit(()->{entered.countDown();try{release.await();synchronized(lock){for(String suffix:new String[]{"",".bak",".new"})Files.write(dir.resolve("entry.json"+suffix),new byte[]{1});saved.set(true);}}catch(Exception e){throw new RuntimeException(e);}});assertTrue(entered.await(3,TimeUnit.SECONDS));CacheIo.remove(io,lock,file.toFile());release.countDown();save.get(3,TimeUnit.SECONDS);io.submit(()->{}).get(3,TimeUnit.SECONDS);assertTrue(saved.get());for(String suffix:new String[]{"",".bak",".new"})assertFalse(Files.exists(dir.resolve("entry.json"+suffix)));}finally{release.countDown();io.shutdownNow();io.awaitTermination(3,TimeUnit.SECONDS);cleanup(dir);}}
 @Test public void removalKeepsTheFileResolvedAtSubmissionTime()throws Exception{List<Runnable> pending=new ArrayList<>();Path dir=Files.createTempDirectory("cache-key-");AtomicReference<String> key=new AtomicReference<>("original");Path original=Files.createFile(dir.resolve("original.json")),later=Files.createFile(dir.resolve("later.json"));try{CacheIo.remove(pending::add,new Object(),dir.resolve(key.get()+".json").toFile());key.set("later");assertTrue(Files.exists(original));pending.remove(0).run();assertFalse(Files.exists(original));assertTrue(Files.exists(later));}finally{cleanup(dir);}}
 @Test public void pruneUsesCapturedKeepSetAndWaitsForCacheExecutor()throws Exception{List<Runnable> pending=new ArrayList<>();Path dir=Files.createTempDirectory("cache-prune-");Set<String> keep=new HashSet<>(Set.of("keep.json"));try{for(String name:List.of("keep.json","keep.json.bak","drop.json","drop.json.new"))Files.createFile(dir.resolve(name));CacheIo.prune(pending::add,new Object(),dir.toFile(),keep);keep.clear();keep.add("drop.json");assertTrue(Files.exists(dir.resolve("drop.json")));pending.remove(0).run();assertTrue(Files.exists(dir.resolve("keep.json")));assertTrue(Files.exists(dir.resolve("keep.json.bak")));assertFalse(Files.exists(dir.resolve("drop.json")));assertFalse(Files.exists(dir.resolve("drop.json.new")));}finally{cleanup(dir);}}
}
